# Let me explicitly check for over-applications
inputs = ['uvfvue', 'kyi', 'hdx', 'cf', 'yzcez']
outputs = ['ghbvfvghbk', 'kyi', 'hdx', 'cf', 'bjkckah']

# Check each rule individually to see if it over-applies
rules_to_check = [('uvf', 'ghb'), ('vue', 'vfvghbk'), ('yzc', 'bjk'), ('ez', 'ckah')]

print("Checking each rule for over-applications:")
for i, (pattern, replacement) in enumerate(rules_to_check):
    print(f"\nRule {i+1}: '{pattern}' -> '{replacement}'")

    # Check each input string
    for j, inp in enumerate(inputs):
        if pattern in inp:
            # Apply the rule to this input
            result = inp.replace(pattern, replacement)
            if result != outputs[j]:
                print(f"  OVER-APPLY: '{inp}' -> '{result}' (expected '{outputs[j]}')")
            else:
                print(f"  OK: '{inp}' -> '{result}'")
        else:
            print(f"  Not found in '{inp}'")

